/* ==UserStyle==
@name         Soft Pink Browser Theme
@namespace    stylish-pink-theme
@version      1.0.0
@description  A soft pink aesthetic browser theme for Stylish / Stylus
@author       You
==/UserStyle== */

/* ---------- Root Colors ---------- */
:root {
    --pink-bg: #ffe6f0;
    --pink-bg-alt: #ffd1e6;
    --pink-accent: #ff6fae;
    --pink-accent-soft: #ff9fc9;
    --pink-text: #4a0033;
    --pink-text-soft: #7a335a;
    --pink-border: #ffb6d9;
}

/* ---------- Global Page Styling ---------- */
html, body {
    background-color: var(--pink-bg) !important;
    color: var(--pink-text) !important;
}

/* ---------- Links ---------- */
a {
    color: var(--pink-accent) !important;
}

a:hover {
    color: var(--pink-text-soft) !important;
    text-decoration: underline;
}

/* ---------- Headings ---------- */
h1, h2, h3, h4, h5, h6 {
    color: #b3005e !important;
}

/* ---------- Inputs & Forms ---------- */
input, textarea, select, button {
    background-color: var(--pink-bg-alt) !important;
    color: var(--pink-text) !important;
    border: 1px solid var(--pink-border) !important;
    border-radius: 6px !important;
}

input::placeholder,
textarea::placeholder {
    color: var(--pink-text-soft) !important;
}

/* ---------- Buttons ---------- */
button,
input[type="submit"],
input[type="button"] {
    background-color: var(--pink-accent-soft) !important;
    color: white !important;
    cursor: pointer;
}

button:hover,
input[type="submit"]:hover,
input[type="button"]:hover {
    background-color: var(--pink-accent) !important;
}

/* ---------- Cards / Sections ---------- */
div, section, article, main {
    border-color: var(--pink-border) !important;
}

/* ---------- Scrollbar (WebKit) ---------- */
::-webkit-scrollbar {
    width: 12px;
}

::-webkit-scrollbar-track {
    background: var(--pink-bg);
}

::-webkit-scrollbar-thumb {
    background-color: var(--pink-accent-soft);
    border-radius: 10px;
    border: 3px solid var(--pink-bg);
}

::-webkit-scrollbar-thumb:hover {
    background-color: var(--pink-accent);
}

/* ---------- Selection ---------- */
::selection {
    background-color: var(--pink-accent-soft);
    color: white;
}

/* ---------- Tables ---------- */
table {
    background-color: var(--pink-bg-alt) !important;
    color: var(--pink-text) !important;
}

th, td {
    border: 1px solid var(--pink-border) !important;
}

